import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"逢尤","description":"","frontmatter":{"title":"逢尤","date":"2026-11-24T00:00:00.000Z","seq":57,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"九叹·远游","link":"/blogs/楚辞/九叹·远游.html"},"next":{"text":"怨上","link":"/blogs/楚辞/怨上.html"}},"headers":[],"relativePath":"blogs/楚辞/逢尤.md","filePath":"blogs/楚辞/逢尤.md"}'),o={name:"blogs/楚辞/逢尤.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="逢尤" tabindex="-1">逢尤 <a class="header-anchor" href="#逢尤" aria-label="Permalink to &quot;逢尤&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">悲兮愁，哀兮忧！</p><p class="poem-stanza">天生我兮当闇时，被诼谮兮虚获尤。</p><p class="poem-stanza">心烦憒兮意无聊，严载驾兮出戏游。</p><p class="poem-stanza">周八极兮历九州，求轩辕兮索重华。</p><p class="poem-stanza">世既卓兮远眇眇，握佩玖兮中路躇。</p><p class="poem-stanza">羡咎繇兮建典谟，懿风后兮受瑞图。</p><p class="poem-stanza">愍余命兮遭六极，委玉质兮於泥涂。</p><p class="poem-stanza">遽傽遑兮驱林泽，步屏营兮行丘阿。</p><p class="poem-stanza">车軏折兮马虺颓，惷怅立兮涕滂沱。</p><p class="poem-stanza">思丁文兮圣明哲，哀平差兮迷谬愚。</p><p class="poem-stanza">吕傅举兮殷周兴，忌嚭专兮郢吴虚。</p><p class="poem-stanza">仰长叹兮气噎结，悒殟绝兮咶复苏。</p><p class="poem-stanza">虎兕争兮於廷中，豺狼斗兮我之隅。</p><p class="poem-stanza">云雾会兮日冥晦，飘风起兮扬尘埃。</p><p class="poem-stanza">走鬯罔兮乍东西，欲窜伏兮其焉如？</p><p class="poem-stanza">念灵闺兮隩重深，原竭节兮隔无由。</p><p class="poem-stanza">望旧邦兮路逶随，忧心悄兮志勤劬。</p><p class="poem-stanza">魂茕茕兮不遑寐，目眽眽兮寤终朝。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
